#!/usr/bin/env bash
# SessionStart hook — give Claude the repository state at the start of a session.
#
# Exit codes for this event:
#   0  continue. Whatever this script prints to stdout is added to Claude's context.
#   2  cannot block a session; Claude Code only shows stderr to the user.
# So this hook always exits 0 and keeps its output short. It runs on every
# session start, so keep it fast.
#
# Generated by tq-forge. Edit freely.

set -uo pipefail

cat >/dev/null  # the hook input arrives as JSON on stdin; this hook does not need it

cd "${CLAUDE_PROJECT_DIR:-.}" 2>/dev/null || exit 0
git rev-parse --is-inside-work-tree >/dev/null 2>&1 || exit 0

branch="$(git rev-parse --abbrev-ref HEAD 2>/dev/null || echo unknown)"
dirty="$(git status --porcelain 2>/dev/null | wc -l | tr -d '[:space:]')"
last="$(git log -1 --pretty='%h %s' 2>/dev/null || echo 'no commits yet')"

printf '%s\n' \
    "Repository state (from the SessionStart hook):" \
    "- Branch: ${branch}" \
    "- Files with uncommitted changes: ${dirty}" \
    "- Last commit: ${last}"

exit 0
